<?php
session_start(); require_once 'conexion.php'; header('Content-Type: application/json; charset=utf-8');
if(empty($_SESSION['usuario_id'])){http_response_code(401);echo json_encode(['ok'=>false,'mensaje'=>'Inicia sesión nuevamente.']);exit;}
$tipo=$_POST['tipo']??'';$nombre=trim($_POST['producto']??$_POST['nombre']??'');$categoria=trim($_POST['categoria']??'');$cantidad=filter_var($_POST['cantidad']??null,FILTER_VALIDATE_INT);$manual=trim($_POST['id']??$_POST['codigo_id']??'');$responsable=$_SESSION['nombre']??'Usuario';
if(!in_array($tipo,['Entrada','Salida'],true)||!$nombre||!$categoria||$cantidad===false||$cantidad<1||($manual!==''&&!ctype_digit($manual))){http_response_code(422);echo json_encode(['ok'=>false,'mensaje'=>'Revisa tipo, producto, categoría, cantidad e ID.']);exit;}
try{$conexion->begin_transaction();$q=$conexion->prepare('SELECT id,categoria,cantidad FROM productos WHERE nombre=? FOR UPDATE');$q->bind_param('s',$nombre);$q->execute();$p=$q->get_result()->fetch_assoc();
if($tipo==='Entrada'){if($p){$id=(int)$p['id'];if($manual!==''&&(int)$manual!==$id)throw new Exception('El producto ya existe y conserva el ID '.$id.'.');if($p['categoria']!==$categoria)throw new Exception('El producto ya existe con otra categoría.');$u=$conexion->prepare('UPDATE productos SET cantidad=cantidad+? WHERE id=?');$u->bind_param('ii',$cantidad,$id);$u->execute();}else{if($manual!==''){$id=(int)$manual;$i=$conexion->prepare('INSERT INTO productos(id,nombre,categoria,cantidad) VALUES(?,?,?,?)');$i->bind_param('issi',$id,$nombre,$categoria,$cantidad);}else{$i=$conexion->prepare('INSERT INTO productos(nombre,categoria,cantidad) VALUES(?,?,?)');$i->bind_param('ssi',$nombre,$categoria,$cantidad);}$i->execute();$id=$conexion->insert_id?:$id;}}else{if(!$p)throw new Exception('No existe ese producto. Registra primero una entrada.');$id=(int)$p['id'];if((int)$p['cantidad']<$cantidad)throw new Exception('No hay existencias suficientes.');$u=$conexion->prepare('UPDATE productos SET cantidad=cantidad-? WHERE id=?');$u->bind_param('ii',$cantidad,$id);$u->execute();}
$m=$conexion->prepare('INSERT INTO movimientos(producto_id,tipo,cantidad,responsable) VALUES(?,?,?,?)');$m->bind_param('isis',$id,$tipo,$cantidad,$responsable);$m->execute();$conexion->commit();echo json_encode(['ok'=>true,'mensaje'=>'Movimiento guardado.','id'=>$id]);}
catch(Throwable $e){$conexion->rollback();http_response_code(422);echo json_encode(['ok'=>false,'mensaje'=>$e->getMessage()]);}
